const sharedIcons={message:'<path d="M5 3h14a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H9l-7 4V6a3 3 0 0 1 3-3Z"/><path d="M7 10h.1M12 10h.1M17 10h.1"/>',bell:'<path d="M5 16c2-2 1-4 2-8a5 5 0 0 1 10 0c1 4 0 6 2 8l1 2H4l1-2ZM10 21q2 2 4 0M12 2V1"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 22v-3a7 7 0 0 1 14 0v3ZM17 4a4 4 0 0 1 0 8M19 16q4 1 4 6h-4"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M3 10h18M7 1v6M17 1v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',alert:'<path d="m12 3 10 18H2L12 3ZM12 9v5M12 17h.1"/>',chevron:'<path d="m9 5 7 7-7 7"/>',note:'<path d="M16 2H5a2 2 0 0 0-2 2v17a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V7l-5-5ZM15 2v6h6M7 12h10M7 17h7M7 7h4"/>',renew:'<path d="M21 9a9 9 0 1 0-1 10M21 3v6h-6"/>',user:'<circle cx="12" cy="6" r="4"/><path d="M4 23v-2a8 8 0 0 1 16 0v2"/>',home:'<path d="m3 10 9-8 9 8v12h-6v-8H9v8H3Z"/>',check:'<rect x="2" y="2" width="20" height="20" rx="3" fill="currentColor"/><path d="m6 12 4 4 8-9" stroke="#151515" stroke-width="2"/>',play:'<circle cx="12" cy="12" r="11"/><path class="play-triangle" d="m10 8 6 4-6 4Z"/>'};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const POSTGREST_URL='http://127.0.0.1:3001';
async function pg(path){const r=await fetch(POSTGREST_URL+path,{headers:{Authorization:'Bearer '+DEV_JWT}});if(!r.ok)throw new Error('API '+r.status+': '+path);return r.json()}
function decodeJwtSub(jwt){try{return JSON.parse(atob(jwt.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).sub}catch{return null}}
function tokyoDate(offsetDays){const d=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const[y,m,dd]=d.split('-').map(Number);return new Date(Date.UTC(y,m-1,dd+offsetDays)).toISOString().slice(0,10)}
function renderIcons(root){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[el.dataset.icon]||''}</svg>`)}
function setBadge(id,count){const el=document.getElementById(id);if(!el)return;if(count>0){el.hidden=false;el.textContent=count>9?'9+':String(count)}else{el.hidden=true}}
